public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 < len) {
                char nextChar = str.charAt(i + 1);
                switch (nextChar) {
                    case 'n':
                        sb.append('\n');
                        i++; // Skip the next character
                        break;
                    case 't':
                        sb.append('\t');
                        i++; // Skip the next character
                        break;
                    case '\\':
                        sb.append('\\');
                        i++; // Skip the next character
                        break;
                    case 'r':
                        sb.append('\r');
                        i++; // Skip the next character
                        break;
                    case 'b':
                        sb.append('\b');
                        i++; // Skip the next character
                        break;
                    case 'f':
                        sb.append('\f');
                        i++; // Skip the next character
                        break;
                    case 'u':
                        if (i + 5 < len) {
                            String hex = str.substring(i + 1, i + 5);
                            int codePoint = Integer.parseInt(hex, 16);
                            sb.append((char) codePoint);
                            i += 4; // Skip the next four characters
                        } else {
                            throw new IllegalArgumentException("Invalid Unicode escape sequence");
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid escape sequence");
                }
            } else {
                throw new IllegalArgumentException("Invalid escape sequence");
            }
        } else {
            sb.append(c);
        }
    }

    return sb.toString();
}

